'use client';
import { useEffect, useRef, useState, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { Avatar, enter, Seg, useGrow } from '../lib/motion';
import { useHoverGlide } from '../lib/glide';
import '../designme.css';
import './notifications.css';

export interface NotificationsItem {
  id: string;
  /** Which filter it belongs to, like 'agent' or 'mention' */
  kind: string;
  /** What happened. Wrap the subject in <b>, like <><b>Pricing audit</b> finished</> */
  text: ReactNode;
  /** Like "4 min ago" */
  time: string;
  /** An icon on a tinted tile, for things the agent did */
  icon?: IconName;
  /** What the icon's tile says: 'ok' (green), 'warn' (amber), 'bad' (red), 'accent' or 'neutral' (grey), each its status's
      tint with its icon in the status's text colour. neutral by default */
  tone?: 'ok' | 'warn' | 'bad' | 'accent' | 'neutral';
  /** A colour of your own for the icon instead of a tone, like 'var(--dm-pl)', on a tint of itself */
  color?: string;
  /** An avatar instead of an icon, for people */
  avatar?: { initials: string; color: string };
  read?: boolean;
}

export interface NotificationsFilter {
  /** 'all' shows everything; anything else shows the items of that kind */
  value: string;
  label: string;
}

export interface NotificationsProps {
  /** Newest first. A new id at the top drops in and bumps the count */
  items?: NotificationsItem[];
  defaultItems?: NotificationsItem[];
  /** Called when items are read or unread, one at a time or all at once */
  onItemsChange?: (items: NotificationsItem[]) => void;
  filters?: NotificationsFilter[];
  /** The open filter. Leave it out to let the switch change it */
  filter?: string;
  defaultFilter?: string;
  onFilterChange?: (filter: string) => void;
  title?: string;
  markAllLabel?: string;
  emptyLabel?: string;
  /** The muted line under emptyLabel */
  emptyDetail?: string;
  className?: string;
}

const FILTERS: NotificationsFilter[] = [{ value: 'all', label: 'All' }, { value: 'agent', label: 'Agent' }, { value: 'mention', label: 'Mentions' }];

/** An inbox where agent updates and mentions arrive live. Click one to mark it read or unread. */
export function Notifications({ items, defaultItems = [], onItemsChange, filters = FILTERS, filter, defaultFilter = 'all', onFilterChange, title = 'Inbox', markAllLabel = 'Mark all read', emptyLabel = 'Nothing here yet', emptyDetail = 'New updates and mentions show up here', className }: NotificationsProps) {
  const [list, setList] = useControllable(items, defaultItems, onItemsChange);
  const [cur, setCur] = useControllable(filter, defaultFilter, onFilterChange);
  const shown = list.filter(x => cur === 'all' || x.kind === cur);
  const unread = list.filter(x => !x.read).length;

  // the rows painted together (on first show and on each filter) stagger in; ones that arrive later drop in on their own
  const [paint, setPaint] = useState(() => ({ filter: cur, ids: shown.map(x => x.id) }));
  if (paint.filter !== cur) setPaint({ filter: cur, ids: shown.map(x => x.id) });
  // a new item bumps the count
  const [known, setKnown] = useState(() => new Set(list.map(x => x.id)));
  const [bump, setBump] = useState(0);
  const fresh = list.filter(x => !known.has(x.id));
  if (fresh.length) { setKnown(new Set([...known, ...fresh.map(x => x.id)])); setBump(b => b + 1); }

  // Mark all read clears the dots one row after another
  const [pending, setPending] = useState<string[]>([]);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
  useEffect(() => () => timers.current.forEach(clearTimeout), []);
  const markAll = () => {
    const rows = shown.filter(x => !x.read).map(x => x.id);
    setPending(rows);
    rows.forEach((id, i) => timers.current.push(setTimeout(() => setPending(p => p.filter(x => x !== id)), i * 50)));
    setList(list.map(x => (x.read ? x : { ...x, read: true })));
  };
  const toggle = (id: string) => setList(list.map(x => (x.id === id ? { ...x, read: !x.read } : x)));
  // the card keeps no room for items to come: it eases taller as one arrives or a filter shows more, and shorter as it shows fewer
  const [root, inner] = useGrow();
  // Clean's one hover: a highlight that glides from item to item
  useHoverGlide(root, '.dm-ntx-n');

  return (
    <div data-dm="" ref={root} className={cx('dm-ntx dm-panel dm-growing', className)}>
      <div ref={inner} className="dm-grow">
      <div className="dm-ntx-h">
        {/* the inbox's mark, in the column the items' icons and avatars sit in */}
        <span className="dm-ntx-hi" aria-hidden="true"><Icon name="bell" /></span>
        <b>{title}</b>
        <span key={bump} className={cx('dm-ntx-ct dm-num', !unread && 'dm-z', bump > 0 && 'dm-bump')} aria-label={`${unread} unread`}>{unread}</span>
        <span className="dm-ntx-sp" />
        <button type="button" className="dm-pill dm-ghost dm-sm dm-ntx-all" onClick={markAll}>{markAllLabel}</button>
      </div>
      <div className="dm-ntx-tabs"><Seg label="Filter" value={cur} onChange={setCur} options={filters} /></div>
      <div key={paint.filter} className="dm-ntx-list">
        {shown.length ? shown.map(x => {
          const at = paint.ids.indexOf(x.id), e = at >= 0 ? enter(at * 40) : null;
          return (
            <button type="button" key={x.id} className={cx('dm-ntx-n', x.read && !pending.includes(x.id) && 'dm-read', e ? e.className : 'dm-new')} style={e?.style}
              aria-pressed={!!x.read} onClick={() => toggle(x.id)}>
              <span className="dm-ic" data-tone={x.avatar || x.color ? undefined : x.tone ?? 'neutral'}
                style={x.avatar || !x.color ? undefined : { color: x.color, background: `color-mix(in srgb,${x.color} 13%,transparent)` }}>
                {x.avatar ? <Avatar initials={x.avatar.initials} color={x.avatar.color} /> : <Icon name={x.icon ?? 'bell'} size="xs" />}
              </span>
              <span className="dm-t">{x.text}<span>{x.time}</span></span>
              <span className="dm-u" />
            </button>
          );
        }) : (
          // an empty filter: a small sketch of a list, a title and one muted line
          <div className="dm-ntx-em"><span className="dm-ntx-em-art" aria-hidden="true" /><b>{emptyLabel}</b>{emptyDetail && <span>{emptyDetail}</span>}</div>
        )}
      </div>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Notifications ---------- */
/* an inbox: a head with its name, the unread count and Mark all read, a filter, then the items, newest first. The rules
   straight under this line are the inbox's parts as the Sales CRM's notifications menu uses them (a bare .ntx in its own
   popover); the component's own card (.ntx.panel, below) sets its own measures over them */
.dm-ntx{padding:var(--dm-s-3);display:flex;flex-direction:column;gap:var(--dm-s-2)}
.dm-ntx-h{display:flex;align-items:center;gap:var(--dm-s-2);margin:0 -12px 2px;padding:2px var(--dm-s-3) 10px var(--dm-s-4);font-size:14px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-ntx-h b{font-weight:500}
.dm-ntx-ct{min-width:20px;height:20px;padding:0 6px;border-radius:var(--dm-r-pill);background:var(--dm-accent);color:var(--dm-on-accent);font-size:11px;font-weight:500;display:grid;place-items:center;transition:transform .35s var(--dm-ease),opacity .3s}
.dm-ntx-ct.dm-z{opacity:0;transform:scale(.5)}
.dm-ntx-ct.dm-bump{animation:dm-ntb .45s var(--dm-ease)}
@keyframes dm-ntb{40%{transform:scale(1.3)}}
.dm-ntx-sp{flex:1}
.dm-ntx-tabs .dm-seg2 button{font-size:12px;height:26px;padding:0 9px}
.dm-ntx-list{display:flex;flex-direction:column}
.dm-ntx-n{display:flex;gap:10px;padding:9px var(--dm-s-2);border-radius:var(--dm-r-in);text-align:left;width:100%;position:relative;transition:background .2s}
@media (hover:hover) and (pointer:fine){.dm-ntx-n:hover{background:var(--dm-row)}}
/* what an agent did: its icon on its status's tint (a finished run green, one that paused amber, a run that started the
   accent), in the status colours (owner, 3 Nov: saturated), never a washed-out mix; a tile given its own colour inline keeps it */
.dm-ntx-n .dm-ic{width:30px;height:30px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;flex:none;background:var(--dm-ntx-tb,transparent);color:var(--dm-ntx-tc,var(--dm-fg2))}
.dm-ntx-n .dm-ic[data-tone="ok"]{--dm-ntx-tb:var(--dm-ok-bg);--dm-ntx-tc:var(--dm-ok)}
.dm-ntx-n .dm-ic[data-tone="warn"]{--dm-ntx-tb:var(--dm-warn-bg);--dm-ntx-tc:var(--dm-warn)}
.dm-ntx-n .dm-ic[data-tone="bad"]{--dm-ntx-tb:var(--dm-bad-bg);--dm-ntx-tc:var(--dm-bad)}
.dm-ntx-n .dm-ic[data-tone="accent"]{--dm-ntx-tb:var(--dm-accent-bg);--dm-ntx-tc:var(--dm-accent-fg)}
.dm-ntx-n .dm-ic[data-tone="neutral"]{--dm-ntx-tb:var(--dm-chip);--dm-ntx-tc:var(--dm-fg2)}
.dm-ntx-n .dm-ic .dm-av{width:30px;height:30px;font-size:11px}
.dm-ntx-n .dm-t{flex:1;min-width:0;font-size:13px;line-height:1.45;color:var(--dm-fg2)}
.dm-ntx-n .dm-t b{font-weight:500;color:var(--dm-fg)}
.dm-ntx-n .dm-t span{display:block;font-size:11.5px;color:var(--dm-muted);margin-top:2px}
.dm-ntx-n .dm-u{width:7px;height:7px;border-radius:50%;background:var(--dm-accent-mark,var(--dm-accent));margin-top:6px;flex:none;transition:transform .3s var(--dm-ease),opacity .3s}
.dm-ntx-n.dm-read .dm-u{transform:scale(0);opacity:0}
.dm-ntx-n.dm-read .dm-t{color:var(--dm-muted)}
.dm-ntx-n.dm-new{animation:dm-ntn .6s var(--dm-ease) both}
@keyframes dm-ntn{from{opacity:0;transform:translateY(-10px);filter:blur(4px)}}
.dm-ntx-e{padding:40px 10px;text-align:center;font-size:13px;color:var(--dm-muted)}
/* the component's own card. It sits on two columns (owner, 18 Nov), its content 16px from every edge in every style: the
   head's neutral mark (the inbox's bell) in a 30px column with each item's icon or avatar centred under it, and the inbox's
   name and each item's words 12px after it; Mark all read's words and the unread dots end on the content's right edge. The
   head's hairline runs from edge to edge with 16px under it. An item is a button, so its hover fill reaches 8px out round it,
   a quiet fill that shows in light mode too, with the card's corners less 8. A read item keeps its colours (owner, 20 Nov:
   nothing fades to say it is past): only its unread dot goes. The card keeps no room for items to come: it grows as they
   arrive (grow()), centred in its stage */
.dm-ntx.dm-panel{padding:var(--dm-s-4);--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
.dm-ntx.dm-panel .dm-ntx-h{gap:var(--dm-s-3);margin:0 calc(-1 * var(--dm-s-4)) var(--dm-s-2);padding:0 var(--dm-s-4) var(--dm-s-4);line-height:20px}
.dm-ntx-hi{width:30px;height:30px;display:grid;place-items:center;flex:none;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);color:var(--dm-fg2)}
.dm-ntx.dm-panel .dm-ntx-ct{margin-left:calc(-1 * var(--dm-s-1))}
/* Mark all read is a text button: its words end on the content's edge and its hover box reaches out round them */
.dm-ntx.dm-panel .dm-ntx-all.dm-pill{padding:0 var(--dm-s-2);margin-right:calc(-1 * var(--dm-s-2))}
.dm-ntx.dm-panel .dm-ntx-tabs{display:flex}
.dm-ntx.dm-panel .dm-ntx-list{margin:0 calc(-1 * var(--dm-s-2)) calc(-1 * var(--dm-s-2))}
.dm-ntx.dm-panel .dm-ntx-n{align-items:center;gap:var(--dm-s-3);padding:var(--dm-s-2);border-radius:calc(var(--dm-r-card) - var(--dm-s-2));transition:background-color var(--dm-t-fast)}
.dm-ntx.dm-panel .dm-ntx-n .dm-t span{line-height:15px}
.dm-ntx.dm-panel .dm-ntx-n .dm-u{margin-top:0}
.dm-ntx.dm-panel .dm-ntx-n.dm-read .dm-t{color:var(--dm-fg2)}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.dm-ntx.dm-panel :is(.dm-pill,.dm-ntx-n):active{transform:none}
/* an empty filter: a small sketch of a list on a white card, a title and one muted line (Clean's empty state, in every style) */
.dm-ntx-em{display:flex;flex-direction:column;align-items:center;gap:4px;padding:var(--dm-s-6) var(--dm-s-4) var(--dm-s-4);text-align:center}
.dm-ntx-em b{font-size:13.5px;line-height:18px;font-weight:500;color:var(--dm-fg)}
.dm-ntx-em>span:not(.dm-ntx-em-art){max-width:290px;font-size:12.5px;line-height:1.5;color:var(--dm-muted)}
.dm-ntx-em-art{position:relative;display:block;width:136px;height:70px;margin:0 0 var(--dm-s-4);border-radius:calc(10px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.dm-ntx-em-art::before{content:"";position:absolute;left:14px;top:14px;width:10px;height:10px;border-radius:50%;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,var(--dm-row))}
.dm-ntx-em-art::after{content:"";position:absolute;left:32px;top:16px;width:58px;height:6px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,var(--dm-row))}
:root:not([data-style="soft"],[data-style="clean"]) .dm-ntx-em-art:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:inset 0 0 0 1px var(--dm-line)}
/* Clean: the head's mark has a hairline like the other tiles, and a new item rises in without a blur */
:root[data-style="clean"] .dm-ntx-hi,:root [data-style="clean"] .dm-ntx-hi,:root [data-style="clean"].dm-ntx-hi{box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .dm-ntx.dm-panel .dm-ntx-n.dm-new,:root [data-style="clean"] .dm-ntx.dm-panel .dm-ntx-n.dm-new,:root [data-style="clean"].dm-ntx.dm-panel .dm-ntx-n.dm-new{animation:dm-clpiece var(--dm-t-slow) var(--dm-ease) both}
